mapper.select:
SELECT org.id, org.parent_id, org.org_name

AND org.parent_id = #{parentId}

    AND EXISTS (
        SELECT 1 FROM sys_org parent
        WHERE parent.id = #{parentId} AND parent.tenant_id = #{tenantId}
            AND parent.org_status = 1 AND parent.del_flag = 0
    )

AND org.id > #{afterOrgId}
ORDER BY org.id
LIMIT #{limit}
